// repro-short-name-length.js
// Usage: node repro-short-name-length.js

const path = require('path');
// Adjust these paths if your working directory is different
const Audit = require(path.join(__dirname, 'lighthouse-core', 'audits', 'manifest-short-name-length.js'));
const manifestParser = require(path.join(__dirname, 'lighthouse-core', 'lib', 'manifest-parser.js'));

function runTest(manifestObj, description) {
  const manifestJson = JSON.stringify(manifestObj);
  const MANIFEST_URL = 'https://example.com/manifest.json';
  const DOC_URL = 'https://example.com/index.html';

  // Parse the manifest into the artifact shape that the audit expects
  const manifestArtifact = manifestParser(manifestJson, MANIFEST_URL, DOC_URL);

  // Run the audit
  const result = Audit.audit({Manifest: manifestArtifact});

  console.log(`\n=== ${description} ===`);
  console.log('Input manifest:', manifestObj);
  console.log('Audit rawValue (pass?):', result.rawValue);
  if (result.debugString) console.log('Debug string:', result.debugString);
  console.log('Display message:', result.displayValue || result.debugString);
}

// Case 1: completely empty manifest
runTest({}, 'Empty manifest (no name, no short_name)');

// Case 2: manifest has name but no short_name
runTest({ name: 'Example Application' }, 'Only name defined, missing short_name');
